cat > /tmp/test_t_function.js << 'EOF'
const { transformSync } = require("@babel/core");
const path = require("path");

// Test cases for t macro with function call syntax
const testCases = [
  {
    name: "t with id and message",
    code: `
import { t } from '@lingui/macro';
const msg = t({
  id: 'msgId',
  message: 'text'
});
`,
    expectedPatterns: ['i18n._(', 'id: "msgId"', 'message: "text"']
  },
  {
    name: "t with id, message, and comment",
    code: `
import { t } from '@lingui/macro';
const msg = t({
  id: 'msgId',
  message: 'text',
  comment: 'description for translators'
});
`,
    expectedPatterns: ['i18n._(', 'id: "msgId"', 'message: "text"', 'comment: "description for translators"']
  },
  {
    name: "t with template literal (should still work)",
    code: `
import { t } from '@lingui/macro';
const msg = t\`Hello World\`;
`,
    expectedPatterns: ['i18n._(', '"Hello World"']
  },
  {
    name: "t with variable interpolation (should still work)",
    code: `
import { t } from '@lingui/macro';
const msg = t\`Hello \${name}\`;
`,
    expectedPatterns: ['i18n._(', '"Hello {name}"', 'name: name']
  }
];

console.log("Testing t macro with function call syntax...\n");

let allPassed = true;

testCases.forEach(({ name, code, expectedPatterns }) => {
  try {
    const result = transformSync(code, {
      filename: "<test>",
      configFile: false,
      presets: [],
      plugins: ["@babel/plugin-syntax-jsx", "macros"],
    });

    const transformedCode = result.code;
    console.log(`✓ ${name}`);
    console.log("  Transformed code:");
    transformedCode.split('\n').forEach(line => {
      if (line.trim() && !line.includes('import')) {
        console.log(`    ${line}`);
      }
    });

    // Check expected patterns
    const missingPatterns = expectedPatterns.filter(pattern => !transformedCode.includes(pattern));
    if (missingPatterns.length > 0) {
      console.log(`  ⚠ Missing patterns: ${missingPatterns.join(', ')}`);
      allPassed = false;
    }
    console.log();
  } catch (e) {
    console.log(`✗ ${name}`);
    console.log(`  Error: ${e.message}`);
    allPassed = false;
    console.log();
  }
});

if (allPassed) {
  console.log("All tests passed! ✓");
} else {
  console.log("Some tests failed! ✗");
  process.exit(1);
}
EOF
